// Posters and validation are generated by default; pass --video to also export MP4.
// node render-rendering-modes.mjs /path/to/tmath-skills/assets/wasm [--preview]
// CPU tmath Lua animation -> H.264 MP4 and poster. No scene rebuilding per frame.
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {spawn} from 'node:child_process';
import {once} from 'node:events';
import sharp from 'sharp';
const dir=path.dirname(fileURLToPath(import.meta.url));
const bundle=path.resolve(process.argv[2]);
const preview=process.argv.includes('--preview');
const output=path.resolve(dir,'../IMAGE/07-SW-Overview');
const temp=path.join(dir,'temp/rendering-modes');
await fs.mkdir(temp,{recursive:true});await fs.mkdir(output,{recursive:true});
const {createTMath}=await import(pathToFileURL(path.join(bundle,'client.js')));
const r=await createTMath('return tmath.scene {width=1600,height=860}', 'bootstrap.lua',{
  renderEngine:'cpu',wasmBinary:await fs.readFile(path.join(bundle,'tmath-wasm.wasm')),
});
r.font('Pretendard',await fs.readFile(path.join(bundle,'Pretendard.ttf')));
const source=await fs.readFile(path.join(dir,'sw-overview-rendering-modes.lua'),'utf8');
const alone=new Set([...source.matchAll(/^-- @standalone: (.*)$/gm)].flatMap(m=>m[1].split(/\s+/)));
const owned=new Map([...source.matchAll(/^-- @contain: (.*)$/gm)].flatMap(m=>m[1].split(/\s+/)).map(s=>{
  const [id,target]=s.split('='),[panel,inset]=target.split(':');return [id,{panel,inset:Number(inset)}];
}));
const right=b=>b.x+b.width,bottom=b=>b.y+b.height;
const clearance=(a,b)=>Math.min(a.x-b.x,a.y-b.y,right(b)-right(a),bottom(b)-bottom(a));
try {
 r.loadLua(source,'sw-overview-rendering-modes.lua');
 const duration=r.duration,[width,height]=r.size(),fps=30;
 const frames=Math.ceil(duration*fps)+1;
 const issues=new Set(),seen=new Set();let minCanvas=Infinity,minPanel=Infinity;
 for(let frame=0;frame<frames;frame++) {
  const time=Math.min(frame/fps,duration),report=r.layoutReport(time,4);
  const byId=new Map(report.objects.map(o=>[o.id,o]));
  const texts=report.objects.filter(o=>o.type==='text'&&o.visible);
  for(const t of texts) {
    seen.add(t.id);const b=t.paintBounds;
    if(!b||b.width<=0||b.height<=0){issues.add(`null bounds: ${t.id}`);continue;}
    const c=clearance(b,{x:0,y:0,width,height});minCanvas=Math.min(c,minCanvas);
    if(c<4)issues.add(`canvas: ${t.id}`);
    if(owned.has(t.id)){
      const {panel,inset}=owned.get(t.id),bb=byId.get(panel)?.paintBounds;
      if(!bb){issues.add(`missing panel: ${panel}`);continue;}
      const n=clearance(b,bb);minPanel=Math.min(n,minPanel);
      if(n<inset)issues.add(`containment: ${t.id}: ${n.toFixed(2)}`);
    }else if(!alone.has(t.id))issues.add(`missing ledger: ${t.id}`);
  }
  for(let i=0;i<texts.length;i++)for(let j=i+1;j<texts.length;j++){
   const a=texts[i].paintBounds,b=texts[j].paintBounds;if(!a||!b)continue;
   if(Math.max(b.x-right(a),a.x-right(b))<4&&Math.max(b.y-bottom(a),a.y-bottom(b))<4)issues.add(`text gap: ${texts[i].id} / ${texts[j].id}`);
  }
  // The engine retains these same objects after initial registration.
  if(time>=2.4) for(const id of ['re_model_a','re_model_b']) {
    const o=byId.get(id);if(!o?.visible)issues.add(`retained identity vanished: ${id}`);
  }
 }
 for(const id of [...alone,...owned.keys()])if(!seen.has(id))issues.add(`unused ledger: ${id}`);
 const summary={duration,width,height,fps,frames,texts:seen.size,minCanvas,minPanel,issues:[...issues]};
 console.log(JSON.stringify(summary));
 await fs.writeFile(path.join(temp,'motion-audit.json'),JSON.stringify(summary,null,2));
 if(issues.size)throw Error('Animation audit failed');
 const raw={width,height,channels:4};
 const samples=[0,1.6,2.7,4.4,6.6,7.6,9.8,12.0,13.2,15.5,duration];
 for(const time of samples.filter(t=>t<=duration)) {
    await sharp(Buffer.from(r.render(time,true)),{raw}).png().toFile(path.join(temp,`motion-${time.toFixed(2)}.png`));
 }
 // Compare actual settled output geometry and colors; no claims about physical time.
 for(const time of [4.4,9.8,duration]) {
   const pixels=Buffer.from(r.render(time,true));
   const crop=top=>sharp(pixels,{raw}).extract({left:1200,top,width:290,height:230}).raw().toBuffer();
   const [a,b]=await Promise.all([crop(195),crop(525)]);
   let maxDifference=0,differentChannels=0;
   for(let i=0;i<a.length;i++){const d=Math.abs(a[i]-b[i]);if(d)differentChannels++;maxDifference=Math.max(maxDifference,d);}
   if(maxDifference>2)throw Error(`Output disagreement @ ${time}: ${maxDifference}`);
   console.log(JSON.stringify({time,maxDifference,differentChannels}));
 }
 // A second asymmetric edit must update every persistent representation.
 const ids=['im_model_a','re_model_a','im_output_a','re_output_a'];
 const originalBounds=ids.map(id=>r.bounds(id,duration));
 r.loadLua(source.replace('local movedA={x=163','local movedA={x=143'),'variant.lua');
 ids.forEach((id,i)=>{
  const delta=r.bounds(id,r.duration).x-originalBounds[i].x;
  if(Math.abs(delta+20)>0.02)throw Error(`Variant dependency failed: ${id}: ${delta}`);
 });
 r.loadLua(source,'sw-overview-rendering-modes.lua');
 const poster=Buffer.from(r.render(duration,true));
 await sharp(poster,{raw}).webp({lossless:true}).toFile(path.join(output,'immediate-retained-mode.webp'));
 await sharp(poster,{raw}).png().toFile(path.join(output,'immediate-retained-mode.png'));
 if (!preview && process.argv.includes('--video')) {
  const encoder=spawn('ffmpeg',['-hide_banner','-loglevel','error','-y','-f','rawvideo','-pixel_format','rgba',
    '-video_size',`${width}x${height}`,'-framerate',String(fps),'-i','pipe:0','-an','-c:v','libx264','-preset','medium',
    '-crf','19','-pix_fmt','yuv420p','-movflags','+faststart',path.join(output,'immediate-retained-mode.mp4')],{stdio:['pipe','inherit','inherit']});
  const completed=once(encoder,'close');
  for(let frame=0;frame<frames;frame++){
    if(!encoder.stdin.write(Buffer.from(r.render(Math.min(frame/fps,duration),true))))await once(encoder.stdin,'drain');
    if(frame%180===0)console.log(`encoding: ${frame}/${frames}`);
  }
  encoder.stdin.end();const[code]=await completed;if(code!==0)throw Error(`ffmpeg: ${code}`);
 }
 console.log('PASS: nine labels, persistent retained objects, matching outputs; motion exported.');
}finally{r.destroy();}
